import http from 'node:http';
import { Readable } from 'node:stream';
import { pathToFileURL } from 'node:url';
import { unpipeAll } from './unpipe.js';

/** Endless source that emits a timestamped line every 100ms. */
function createTicker() {
  let timer;
  return new Readable({
    read() {
      if (timer) return;
      timer = setInterval(() => {
        this.push(`${new Date().toISOString()}\n`);
      }, 100);
    },
    destroy(err, cb) {
      clearInterval(timer);
      cb(err);
    },
  });
}

export function createServer() {
  return http.createServer((req, res) => {
    if (req.method === 'GET' && req.url === '/health') {
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ status: 'ok' }));
      return;
    }

    if (req.method === 'GET' && req.url === '/stream') {
      const source = createTicker();
      res.writeHead(200, { 'content-type': 'text/plain; charset=utf-8' });
      source.pipe(res);

      // When the client goes away, detach the source from every destination
      // before destroying it so nothing writes to a closed socket.
      res.on('close', () => {
        unpipeAll(source);
        source.destroy();
      });
      return;
    }

    res.writeHead(404, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ error: 'not found' }));
  });
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const port = Number(process.env.PORT) || 3000;
  const server = createServer();
  server.listen(port, () => {
    console.log(`listening on http://localhost:${port}`);
  });

  const shutdown = () => server.close(() => process.exit(0));
  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);
}
EOF
cat > test/unpipe.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { PassThrough, Writable } from 'node:stream';
import { unpipeAll } from '../src/unpipe.js';

test('removes every pipe destination', () => {
  const source = new PassThrough();
  const a = new PassThrough();
  const b = new PassThrough();
  const c = new PassThrough();

  source.pipe(a);
  source.pipe(b);
  source.pipe(c);
  assert.equal(source.listenerCount('data'), 3);

  unpipeAll(source);

  assert.equal(source.listenerCount('data'), 0);
  assert.equal(source.readableFlowing, false);
});

test('emits unpipe on each destination', () => {
  const source = new PassThrough();
  const dests = [new PassThrough(), new PassThrough()];
  const seen = [];

  for (const d of dests) {
    d.on('unpipe', (src) => seen.push(src));
    source.pipe(d);
  }

  unpipeAll(source);

  assert.deepEqual(seen, [source, source]);
});

test('destinations receive no data after unpipe', async () => {
  const source = new PassThrough();
  const chunks = [];
  const sink = new Writable({
    write(chunk, _enc, cb) {
      chunks.push(chunk.toString());
      cb();
    },
  });

  source.pipe(sink);
  source.write('before');
  await new Promise((r) => setImmediate(r));

  unpipeAll(source);
  source.write('after');
  await new Promise((r) => setImmediate(r));

  assert.deepEqual(chunks, ['before']);
});

test('is safe on a stream with no destinations', () => {
  const source = new PassThrough();
  assert.equal(unpipeAll(source), source);
  assert.equal(unpipeAll(source), source);
});

test('throws on non-streams', () => {
  assert.throws(() => unpipeAll(), TypeError);
  assert.throws(() => unpipeAll({}), TypeError);
});
EOF
cat > test/server.test.js <<'EOF'
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import { createServer } from '../src/server.js';

let server;
let base;

before(async () => {
  server = createServer();
  await new Promise((r) => server.listen(0, r));
  base = `http://localhost:${server.address().port}`;
});

after(() => new Promise((r) => server.close(r)));

test('GET /health', async () => {
  const res = await fetch(`${base}/health`);
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { status: 'ok' });
});

test('GET /stream streams data and cleans up on client abort', async () => {
  const firstChunk = await new Promise((resolve, reject) => {
    const req = http.get(`${base}/stream`, (res) => {
      assert.equal(res.statusCode, 200);
      res.once('data', (chunk) => {
        req.destroy();
        resolve(chunk.toString());
      });
    });
    req.on('error', (err) => {
      if (err.code !== 'ECONNRESET') reject(err);
    });
  });

  assert.match(firstChunk, /^\d{4}-\d{2}-\d{2}T/);
});

test('unknown route returns 404', async () => {
  const res = await fetch(`${base}/nope`);
  assert.equal(res.status, 404);
});
EOF
